const $ = (s) => document.querySelector(s);
const esc = (s) => String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const pj = (o) => esc(JSON.stringify(o, null, 2));
const cur = () => DATA[S.sc];
const curQ = () => cur().quiz[S.q.i];

function loadProgress() {
  try {
    return JSON.parse(localStorage.getItem(PROGRESS_KEY) || "{}");
  } catch {
    return {};
  }
}

function markScenarioDone(id) {
  try {
    const progress = loadProgress();
    progress[id] = true;
    localStorage.setItem(PROGRESS_KEY, JSON.stringify(progress));
  } catch {
    // Ignore storage quota / privacy mode errors.
  }
  syncNavProgress();
}

function syncNavProgress() {
  const progress = loadProgress();
  document.querySelectorAll(".lesson-nav a[data-scene]").forEach((link) => {
    link.classList.toggle("is-done", Boolean(progress[link.dataset.scene]));
  });
}

function nameOf(key) {
  if (!key) return "";
  const i = key.indexOf(":"), t = key.slice(0, i), id = key.slice(i + 1);
  if (t === "doc") {
    const [k, c] = id.split("@");
    return k + "（会话 " + c.slice(2) + "）";
  }
  return ({ conversation: "会话", submission: "Submission", entry: "Entry", task: "Task" })[t] + " #" + id;
}

function buildCommitIndexes(scenario) {
  const commits = [new Map()];
  for (const row of scenario.rows) {
    const state = new Map(commits.at(-1));
    row.x.forEach((item, index) => {
      if (item.key) {
        state.set(item.key, { row: row.q, index, item });
      } else if (item.n === 2 && item.a?.retire) {
        const suffix = "@" + item.a.retire;
        for (const key of state.keys()) {
          if (key.startsWith("doc:") && key.endsWith(suffix)) state.delete(key);
        }
      }
    });
    commits.push(state);
  }
  return commits;
}

function recordTitle(item) {
  if (!item.key) return item.t;
  if (item.c === 4) return item.key.slice("doc:".length).replace("@", " @ ");
  const type = ["会话", "Submission", "Entry", "Task"][item.c];
  return type + " #" + item.a.id;
}

function recordLinks(item, currentState) {
  if (!item.key) return [];
  const record = item.a;
  const links = new Map();
  const add = (field, type, id) => {
    if (!Number.isInteger(id)) return;
    const key = type + ":" + id;
    if (key !== item.key && currentState.has(key) && !links.has(key)) {
      links.set(key, { field, key });
    }
  };

  switch (item.c) {
    case 0:
      add("owner.task_id", "task", record.owner?.task_id);
      add("owner.conversation_id", "conversation", record.owner?.conversation_id);
      break;
    case 1:
      add("entry", "entry", record.entry);
      add("answer", "entry", record.answer);
      break;
    case 2:
      add("by_task_id", "task", record.by_task_id);
      break;
    case 3: {
      const checkpoint = record.state?.checkpoint;
      add("owner", "task", record.owner);
      (record.state?.on ?? []).forEach((id, i) => add("state.on[" + i + "]", "task", id));
      if (record.kind === "pi.generation") {
        add("state.checkpoint.assistant", "entry", checkpoint?.assistant);
        add("state.checkpoint.cutoff", "entry", checkpoint?.cutoff);
        if (checkpoint?.phase === "tools") {
          (checkpoint.tools ?? []).forEach((id, i) => add("state.checkpoint.tools[" + i + "]", "task", id));
        }
      }
      if (record.kind === "pi.tool") add("input.assistant", "entry", record.input?.assistant);
      if (record.kind === "pi.generation" || record.kind === "pi.tool") {
        add("state.outcome.result.entry_id", "entry", record.state?.outcome?.result?.entry_id);
      }
      break;
    }
    case 4: {
      if (item.t === "pi.live") {
        add("run.task_id", "task", record.run?.task_id);
        (record.run?.inputs ?? []).forEach((input, i) => {
          add("run.inputs[" + i + "].id", "submission", input.id);
          add("run.inputs[" + i + "].entry", "entry", input.entry);
        });
        add("generation.task_id", "task", record.generation?.task_id);
        for (const [callId, slot] of Object.entries(record.tools ?? {})) {
          add("tools[" + JSON.stringify(callId) + "].task_id", "task", slot.task_id);
        }
      } else if (item.t === "pi.inbox") {
        (record.items ?? []).forEach((input, i) => add("items[" + i + "].id", "submission", input.id));
      }
      const address = item.key.slice(item.key.lastIndexOf("@") + 1);
      const [scope, id] = address.split(":");
      if (scope === "c") add("文档地址 " + address, "conversation", Number(id));
      if (scope === "t") add("文档地址 " + address, "task", Number(id));
      break;
    }
  }
  add("conversation_id", "conversation", record.conversation_id);
  return [...links.values()];
}

function commitSource(row) {
  const by = row.by;
  if (by.startsWith("harness.root")) return { path: "pi_durable/harness/harness.py", line: 125, fn: "Harness.root()" };
  if (by.startsWith("conversation.submit")) return { path: "pi_durable/harness/submissions.py", line: 44, fn: "admit()" };
  if (by.startsWith("conversation.abort")) return { path: "pi_durable/harness/harness.py", line: 284, fn: "Conversation.abort()" };
  if (by.startsWith("Harness.open")) return { path: "pi_durable/scheduler.py", line: 92, fn: "TaskScheduler.open()" };
  if (by.startsWith("调度器：_reconcile")) return { path: "pi_durable/scheduler.py", line: 224, fn: "TaskScheduler._reconcile()" };
  if (by.startsWith("调度器：")) return { path: "pi_durable/scheduler.py", line: 300, fn: "TaskScheduler._reserve()" };
  if (by.startsWith("pi.generation：prepare")) return { path: "pi_durable/harness/generation.py", line: 60, fn: "prepare()" };
  if (by.startsWith("pi.generation：处理模型回复")) return { path: "pi_durable/harness/generation.py", line: 125, fn: "_classify()" };
  if (by.startsWith("pi.generation：tools")) return { path: "pi_durable/harness/generation.py", line: 184, fn: "tools_phase()" };
  if (by.startsWith("pi.generation：abort")) return { path: "pi_durable/harness/generation.py", line: 231, fn: "abort_generation()" };
  if (by.startsWith("pi.tool：提交意图")) return { path: "pi_durable/harness/tool.py", line: 158, fn: "call_phase()" };
  if (by.startsWith("pi.tool：刷出部分输出")) return { path: "pi_durable/harness/tool.py", line: 47, fn: "ToolApi.flush()" };
  if (by.startsWith("pi.tool：恢复")) return { path: "pi_durable/harness/tool.py", line: 167, fn: "execute_phase()" };
  if (by.startsWith("pi.tool：提交结果")) return { path: "pi_durable/harness/tool.py", line: 101, fn: "_commit_result()" };
  if (by.startsWith("pi.tool：abort")) return { path: "pi_durable/harness/tool.py", line: 182, fn: "abort_tool()" };
  if (by === "subagent 工具：创建子会话") return { path: "pi_durable/session.py", line: 246, fn: "create_conversation()" };
  if (by === "subagent 工具：向子会话 submit()") return { path: "pi_durable/harness/submissions.py", line: 44, fn: "admit()" };
  return null;
}

const COMMIT_INDEXES = DATA.map(buildCommitIndexes);

function chipCls(x) { return x.n === 2 ? "ret" : x.n === 1 ? "new" : "upd"; }

function visibleRows() {
  const rows = cur().rows;
  if (S.mode === "quiz" && S.q && !S.q.finished) {
    const question = curQ();
    return rows.slice(0, S.q.revealed ? question.step + 1 : question.step);
  }
  return S.mode === "quiz" || S.revealAll ? rows : rows.slice(0, S.open?.q ?? 1);
}

/* Sequence diagram events */
function sequenceEvents(scenario) {
  const events = scenario.rows.map(() => []);
  const emit = (row, from, to, label, detail, after = false) => {
    events[row.q - 1].push({ from, to, label, detail, after });
  };
  const root = scenario.rows[0];
  emit(root, "user", "harness", "初始化会话", "示例程序先调用 harness.root()。会话和 pi.agent 在随后的同一批提交中创建。");

  for (const [i, row] of scenario.rows.entries()) {
    const previous = scenario.rows[i - 1];
    const taskWrites = row.x.filter((item) => item.c === 3);
    const entryWrites = row.x.filter((item) => item.c === 2);
    const submissions = row.x.filter((item) => item.c === 1);
    const task = taskWrites[0]?.a;

    if (row.by.startsWith("Harness.open")) {
      emit(row, "user", "harness", "新进程打开存储", "新进程调用 Harness.open(storage)，扫描存储并将崩溃时仍为 running 的任务改回 pending、restarts + 1。");
    }

    if (scenario.crashAfter && row.q === scenario.crashAfter + 2) {
      emit(row, "user", "harness", "重发 request_id（幂等命中 #2）", "重启后调用方用同一个 request_id: buy-1 再次调用 submit()，admit() 直接返回已有的 Submission #2，不新增写入，并唤醒 Scheduler。");
    }

    if (row.by.startsWith("conversation.abort")) {
      emit(row, "user", "harness", "调用 conversation.abort()", "用户打断主会话。同一事务清空 pi.inbox 里的排队输入，并只给主会话顶层 Task #4 打上 abort_requested: true。");
    }

    if (row.by.startsWith("conversation.submit()")) {
      const submission = submissions[0]?.a;
      const entry = entryWrites.find((item) => item.a.id === submission?.entry);
      const inbox = row.x.find((item) => item.key?.startsWith("doc:pi.inbox@"));
      const queued = inbox?.a.items?.find((item) => item.id === submission?.id);
      const message = entry?.a.model?.[0]?.content ?? queued?.content;
      const label = submission?.type === "write" ? "提交展示条目" :
        submission?.status !== "queued" ? "发送用户问题" :
          queued?.mode === "steer" ? "发送纠正消息" : "发送跟进问题";
      const detail = submission?.type === "write"
        ? "调用 submit({type: 'write', ...})。本例的 chat.note 直接写成展示条目。"
        : "调用 conversation.submit()。" + (typeof message === "string" ? "输入：" + message : "") +
          (submission?.status === "queued" ? "此时会话忙，这个输入先进入 pi.inbox。" : "");
      emit(row, "user", "harness", label, detail);
    }

    if (previous?.by.startsWith("调度器：领走任务") || previous?.by.startsWith("调度器：预留 abort")) {
      for (const reserved of previous.x.filter((item) => item.c === 3)) {
        const id = reserved.a.id;
        const phase = reserved.a.state?.checkpoint?.phase;
        const observed = scenario.runtime[i].scheduler._invocations[id];
        if (observed) {
          const isAbort = observed.mode === "abort";
          emit(
            row,
            "scheduler",
            "worker",
            (isAbort ? "启动 abort 调用 #" : "启动 Task #") + id,
            isAbort
              ? "所有子工作已排空，调度器在预留后以 mode: \"abort\" 启动 Task #" + id + "，执行它的 abort 处理器。"
              : "调度器在上一批提交把任务写成 running 后，才启动调用并把它放进 _invocations。进入 " + phase + " 阶段。"
          );
        }
      }
    }

    if (row.by.startsWith("调度器：_reconcile")) {
      emit(row, "scheduler", "worker", "取消正在跑的 run 调用", "_observe() 看到新出现的 abort_requested: true 后，立刻向内存中正在执行的 run 调用发出取消信号。", true);
    }

    if (row.by.startsWith("pi.generation：prepare") && task?.state.checkpoint?.phase === "request") {
      const { model, cutoff } = task.state.checkpoint;
      emit(row, "worker", "external", "请求模型 " + model,
        "prepare 先保存模型、工具名单和上下文截止点（Entry #" + cutoff +
        "）。之后 request 从这些信息构建请求并调用 model.stream()。", true);
    }

    if (row.by.startsWith("pi.generation：处理模型回复")) {
      const reply = entryWrites.find((item) => item.a.kind === "pi.assistant")?.a.model?.[0];
      if (reply) {
        const tools = (reply.tool_calls ?? []).map((call) => call.name);
        emit(row, "external", "worker", tools.length ? "返回工具调用" : "返回模型回答",
          tools.length ? "模型请求调用 " + tools.join("、") +
            "。模型只给出调用指令，生成任务随后提交 assistant 条目和待运行的工具任务。" :
            "模型流返回本轮最终消息。生成任务随后把该消息写成 assistant 条目。");
      }
    }

    if (row.by.startsWith("pi.tool：提交意图")) {
      const live = row.x.find((item) => item.key?.startsWith("doc:pi.live@"));
      const tool = Object.values(live?.a.tools ?? {}).find((slot) => slot.task_id === task?.id);
      if (tool) {
        emit(row, "worker", "external", "调用 " + tool.name,
          "工具任务先将运行意图、参数和 replay 策略写入存储。提交成功后，才调用工具的 execute 方法。", true);
      }
    }

    if (row.by.startsWith("pi.tool：刷出部分输出")) {
      emit(row, "external", "worker", "流式输出并 flush()", "charge_card 调用 api.output() 与 api.flush()，把部分输出落盘到 pi.live.tools，崩溃后恢复仍能读到它。");
    }

    if (row.by.startsWith("pi.tool：恢复执行")) {
      const result = entryWrites.find((item) => item.a.kind === "pi.tool-result")?.a.model?.[0];
      if (result) {
        emit(row, "worker", "external", "安全重跑 " + result.name, "execute_phase 确认 replay=\"safe\"，用 checkpoint 中存下的参数重新执行 " + result.name + " 并拿到结果。");
      }
    }

    if (row.by === "subagent 工具：创建子会话") {
      emit(row, "external", "worker", "申请创建子会话",
        "subagent 工具通过 TaskRuntime.commit() 创建会话 #7 和该会话的 pi.agent。会话的 owner 指向工具任务 #6。");
    }

    if (row.by === "subagent 工具：向子会话 submit()") {
      emit(row, "external", "harness", "向子会话提问",
        "subagent 工具取得会话 #7 的句柄并调用 child.submit()，然后等待子会话的 Submission #8。");
    }

    if (row.by.startsWith("pi.tool：提交结果")) {
      if (scenario.id === "subagent") {
        emit(row, "harness", "external", "子会话已回答",
          "上一批已经保存子会话的回答。工具等到 Submission #8 结算后，根据 answer 读出子会话的回答文本。");
      }
      const result = entryWrites.find((item) => item.a.kind === "pi.tool-result")?.a.model?.[0];
      if (result) {
        emit(row, "external", "worker", "返回工具结果",
          "工具 " + result.name + " 的返回值交给工具任务。接下来才写入 tool-result 条目、任务结果和工具槽位。");
      }
    }

    if (i === scenario.rows.length - 1 && submissions.some((item) => item.a.status === "done" || item.a.status === "unanswered")) {
      const abortedEnd = submissions.some((item) => item.a.status === "unanswered");
      emit(
        row,
        "harness",
        "user",
        abortedEnd ? "中止完成，返回 unanswered" : "等待结果返回",
        abortedEnd
          ? "主会话的 Submission #2 已结算为 unanswered（aborted），整棵所有权树全部清理完毕，wait() 与 abort() 返回。"
          : "回答条目和 Submission 的 done 状态已提交。调用方的 wait() 返回，answer 保存回答条目的 ID。",
        true
      );
    }
  }
  return events;
}

function persistenceSender(row) {
  if (row.by.startsWith("调度器") || row.by.startsWith("Harness.open")) return "scheduler";
  if (/^(harness\.|conversation\.)/.test(row.by) || row.by.includes("向子会话 submit()")) return "harness";
  return "worker";
}

function persistenceLabels(row) {
  const entryKinds = {
    "pi.user": "用户消息",
    "pi.assistant": "模型回复",
    "pi.tool-result": "工具结果",
    "pi.system": "系统条目",
  };
  return row.x.map((item) => {
    const value = item.a;
    if (item.n === 2) return { text: "清理任务文档 " + value.retire, warn: false };
    const created = item.n === 1;
    switch (item.c) {
      case 0:
        return {
          text: (created ? "新增" : "更新") + "会话 #" + value.id +
            (value.owner?.task_id ? "（归属 #" + value.owner.task_id + "）" : ""),
          warn: false,
        };
      case 1: {
        const isUnanswered = value.status === "unanswered";
        return {
          text: (created ? "+" : "") + "Submission #" + value.id + (created ? " · " : " → ") + value.status +
            (value.answer ? "（回答 #" + value.answer + "）" : value.reason ? "（" + value.reason + "）" : ""),
          warn: isUnanswered,
        };
      }
      case 2: {
        const isErr = Boolean(value.model?.[0]?.is_error);
        return {
          text: (created ? "+" : "") + "Entry #" + value.id +
            (entryKinds[value.kind] ? "（" + entryKinds[value.kind] + (isErr ? "·错" : "") + "）" : ""),
          warn: isErr,
        };
      }
      case 3: {
        const state = value.state;
        const phase = state.checkpoint?.phase;
        const outcome = state.outcome?.status;
        const suffix = phase ? "/" + phase : outcome ? "/" + outcome : "";
        let extra = "";
        if (value.restarts && value.restarts !== item.b?.restarts) extra += " · restarts=" + value.restarts;
        if (value.abort_requested && !item.b?.abort_requested) extra += " · abort=true";
        if (row.by.startsWith("调度器：预留 abort")) extra += "（预留 abort）";
        const warn = Boolean(extra) || outcome === "failed" || outcome === "aborted";
        return {
          text: (created ? "+" : "") + "Task #" + value.id + (created ? " · " : " → ") + state.status + suffix + extra,
          warn,
        };
      }
      case 4: {
        const address = item.key.slice(item.key.lastIndexOf("@") + 1);
        const doc = (created ? "+" : "") + item.t + " " + address;
        switch (item.t) {
          case "pi.agent":
            return { text: doc + (typeof value.model === "string" ? "（" + value.model + "）" : ""), warn: false };
          case "pi.live": {
            const run = value.run;
            if (run?.task_id && (created || item.b?.run?.task_id !== run.task_id)) {
              return { text: doc + " → Task #" + run.task_id, warn: false };
            }
            if (!run && item.b?.run) return { text: doc + "（清空 run）", warn: false };
            const slots = Object.values(value.tools ?? {});
            const prevSlots = item.b?.tools ?? {};
            for (const [cid, slot] of Object.entries(value.tools ?? {})) {
              if (slot.output && slot.output !== prevSlots[cid]?.output && slot.status === "running") {
                return { text: doc + "（刷出 " + slot.name + " 输出）", warn: false };
              }
            }
            if (slots.length === 1) return { text: doc + "（工具 " + slots[0].status + "）", warn: false };
            if (slots.length > 1) return { text: doc + "（" + slots.length + " 个工具槽位）", warn: false };
            return { text: doc, warn: false };
          }
          case "pi.inbox": {
            const now = new Set(value.items?.map(({ id }) => id));
            const previous = new Set(item.b?.items?.map(({ id }) => id));
            const inserted = [...now].filter((id) => !previous.has(id));
            const removed = [...previous].filter((id) => !now.has(id));
            if (inserted.length === 1 && !removed.length) return { text: doc + "（入队 #" + inserted[0] + "）", warn: false };
            if (removed.length === 1 && !inserted.length) return { text: doc + "（取出 #" + removed[0] + "）", warn: false };
            return { text: doc, warn: false };
          }
          default:
            return { text: doc, warn: false };
        }
      }
      default:
        return { text: item.t, warn: false };
    }
  });
}

const PARTICIPANTS = [
  { id: "user", title: "用户", short: "用户", sub: "请求 / 回执" },
  { id: "harness", title: "会话", short: "会话", sub: "Conversation / Harness" },
  { id: "scheduler", title: "调度器", short: "调度", sub: "Scheduler" },
  { id: "worker", title: "任务调用", short: "调用", sub: "Invocation" },
  { id: "external", title: "模型 / 工具", short: "模型 / 工具", sub: "执行方" },
  { id: "storage", title: "DB", short: "DB", sub: "Storage" },
];
const PARTICIPANT_BY_ID = new Map(PARTICIPANTS.map((p, i) => [p.id, { ...p, index: i }]));
const EVENT_ROWS = DATA.map(sequenceEvents);

function activeMessage(row) {
  if (!S.open || S.open.q !== row.q || !Number.isInteger(S.open.event)) return null;
  return EVENT_ROWS[S.sc][row.q - 1][S.open.event] || null;
}

function arrowHTML(row, from, to, label, inner, event) {
  const origin = PARTICIPANT_BY_ID.get(from), target = PARTICIPANT_BY_ID.get(to);
  const start = Math.min(origin.index, target.index);
  const span = Math.abs(origin.index - target.index) + 1;
  const storage = event === null;
  const backwards = origin.index > target.index;
  const active = S.open?.q === row.q && (storage ? !Number.isInteger(S.open.event) : S.open.event === event);
  const rowTitle = storage ? "第 " + row.q + " 次写入 DB（" + row.x.length + " 项）" :
    origin.title + " → " + target.title + "：" + label;
  return '<div class="message-row"><button type="button" class="message ' +
    (storage ? "store-message" : "runtime-message") + (backwards ? " reversed" : "") +
    '" data-act="' + (storage ? "db" : "event") + '" data-q="' + row.q + '"' +
    (storage ? "" : ' data-e="' + event + '"') + ' aria-pressed="' + active +
    '" aria-label="' + esc(rowTitle) + '" style="--line-start:' + (start + 1) +
    ";--line-end:" + (start + span + 1) + ";--edge:" + (50 / span).toFixed(5) + '%">' +
    '<span class="message-content">' + inner + '</span><span class="message-line" aria-hidden="true"></span></button></div>';
}

function sequenceHTML(rows) {
  const header = '<div class="sequence-head"><span class="sequence-time" aria-label="时间从上往下">时间 <span aria-hidden="true">↓</span></span>' +
    '<div class="message-grid">' + PARTICIPANTS.map((p) =>
      '<div class="participant participant-' + p.id + '">' +
      (p.id === "storage" ? '<span class="db-icon" aria-hidden="true"></span>' : "") +
      '<div><strong aria-label="' + esc(p.title) + '"><span class="participant-full">' + esc(p.title) +
      '</span><span class="participant-short" aria-hidden="true">' + esc(p.short) + "</span></strong>" +
      "<small>" + esc(p.sub) + "</small></div></div>"
    ).join("") + "</div></div>";
  if (!rows.length) return header + '<p class="sequence-empty">时序图还没有展开到第一次提交。</p>';

  const crashAfter = cur().crashAfter || 0;
  const groups = rows.map((row) => {
    const events = EVENT_ROWS[S.sc][row.q - 1].map((event, i) => ({
      after: event.after,
      html: arrowHTML(row, event.from, event.to, event.label, '<span class="runtime-label">' + esc(event.label) + "</span>", i),
    }));
    const writes = persistenceLabels(row).map(({ text, warn }, i) => {
      const op = row.x[i].n;
      const cls = op === 2 ? " write-cleanup" : warn ? " write-warn" : "";
      return '<span class="write-tag' + cls + '">' + esc(text) + "</span>";
    }).join("");
    const db = arrowHTML(row, persistenceSender(row, cur()), "storage", "",
      '<span class="commit-label">写入 DB</span><span class="write-tags">' + writes + "</span>", null);
    const divider = crashAfter && row.q === crashAfter + 1
      ? '<div class="crash-divider" role="separator"><span class="crash-divider-badge">CRASH</span>' +
        "<span>进程在此突然崩溃（simulate_crash / os._exit）：不写 DB、内存全清，DB 留下 running 的 #6、#7 与 waiting 的 #4 → 新进程启动 Harness.open()</span></div>"
      : "";
    return divider + '<div class="sequence-group' + (S.open?.q === row.q ? " current-group" : "") + '" data-step="' + row.q + '">' +
      '<div class="step-gutter"><span class="step-number" aria-label="第 ' + row.q + ' 次提交">' + row.q + "</span></div>" +
      '<div class="group-messages"><div class="lifelines message-grid" aria-hidden="true">' +
      PARTICIPANTS.map((p) => '<span class="' + (p.id === "storage" ? "storage-lifeline" : "") + '"></span>').join("") + "</div>" +
      events.filter((e) => !e.after).map((e) => e.html).join("") + db +
      events.filter((e) => e.after).map((e) => e.html).join("") + "</div></div>";
  });
  return header + groups.join("");
}

function showStep(insideDiagram = false) {
  const inspector = $("#commit-inspector");
  if (!inspector) return;
  if (insideDiagram) {
    const group = $('.sequence-group[data-step="' + S.open.q + '"]');
    const scroll = $("#sequence-scroll");
    if (group && scroll) {
      const bounds = scroll.getBoundingClientRect();
      const visibleTop = bounds.top + $(".sequence-head").getBoundingClientRect().height;
      if (group.getBoundingClientRect().top < visibleTop || group.getBoundingClientRect().bottom > bounds.bottom) {
        scroll.scrollTop += group.getBoundingClientRect().top - visibleTop;
      }
    }
  } else {
    const top = inspector.getBoundingClientRect().top;
    if (top > window.innerHeight - 120) inspector.scrollIntoView({ block: "start" });
  }
}

function refButton(key, label, field = "", at = null) {
  return '<button type="button" class="ref" data-act="ref" data-ref="' + esc(key) + '"' +
    (at ? ' data-at="' + at + '"' : "") + ">" +
    (field ? "<code>" + esc(field) + '</code><span aria-hidden="true">→</span>' : "") +
    "<span>" + esc(label) + "</span></button>";
}

/* Live World State Board: compact overview of Entries, Submissions/Inbox, and Task Ownership Tree at commit #at */
function worldStateHTML(row, state) {
  const at = row.q;
  const touched = new Set(row.x.map((item) => item.key).filter(Boolean));
  const selectedKey = S.open.ref || (S.open.i >= 0 ? row.x[S.open.i]?.key : null);

  const conversations = new Map();
  const entries = [];
  const submissions = [];
  const tasks = [];
  const liveDocs = new Map();
  const inboxDocs = new Map();

  for (const { item } of state.values()) {
    if (item.c === 0) conversations.set(item.a.id, item.a);
    else if (item.c === 1) submissions.push(item);
    else if (item.c === 2) entries.push(item);
    else if (item.c === 3) tasks.push(item);
    else if (item.c === 4 && item.t === "pi.live") {
      const cid = Number(item.key.split("@c:")[1]);
      if (Number.isInteger(cid)) liveDocs.set(cid, item.a);
    } else if (item.c === 4 && item.t === "pi.inbox") {
      const cid = Number(item.key.split("@c:")[1]);
      if (Number.isInteger(cid)) inboxDocs.set(cid, item.a);
    }
  }
  entries.sort((a, b) => a.a.id - b.a.id);
  submissions.sort((a, b) => a.a.id - b.a.id);
  tasks.sort((a, b) => a.a.id - b.a.id);

  const multiConv = conversations.size > 1;
  const itemCls = (key) => "world-item" + (touched.has(key) ? " world-touched" : "") + (selectedKey === key ? " world-selected" : "");

  // Column 1: Entries
  const entriesByConv = new Map();
  for (const e of entries) {
    const cid = e.a.conversation_id;
    if (!entriesByConv.has(cid)) entriesByConv.set(cid, []);
    entriesByConv.get(cid).push(e);
  }
  let entriesHTML = '<p class="world-empty">还没有写入对话消息。</p>';
  if (entries.length) {
    entriesHTML = [...entriesByConv].map(([cid, list]) => {
      const heading = multiConv ? '<div class="world-conv-label">会话 #' + cid + (conversations.get(cid)?.owner ? "（子会话）" : "（主会话）") + "</div>" : "";
      return heading + list.map((e) => {
        const msg = e.a.model?.[0];
        let text = "";
        if (msg?.tool_calls?.length) {
          text = "→ " + msg.tool_calls.map((c) => c.name + "()").join(", ");
        } else if (typeof msg?.content === "string" && msg.content) {
          text = msg.content.length > 32 ? msg.content.slice(0, 31) + "…" : msg.content;
        } else if (e.a.data?.text) {
          text = e.a.data.text;
        }
        const kindShort = e.a.kind.replace(/^pi\./, "");
        const errPill = msg?.is_error ? '<span class="pill pill-bad">error</span>' : "";
        return '<button type="button" class="' + itemCls(e.key) + '" data-act="ref" data-ref="' + esc(e.key) + '" data-at="' + at + '">' +
          '<span class="world-item-main">#' + e.a.id + " " + esc(kindShort) + "</span>" + errPill +
          (text ? '<span class="world-item-text">' + esc(text) + "</span>" : "") + "</button>";
      }).join("");
    }).join("");
  }

  // Column 2: Submissions & Inbox
  let subsHTML = '<p class="world-empty">还没有提交请求。</p>';
  if (submissions.length) {
    subsHTML = submissions.map((s) => {
      const v = s.a;
      const convTag = multiConv ? '<span class="pill pill-pending">c:' + v.conversation_id + "</span>" : "";
      const extra = v.answer ? " → #" + v.answer : v.reason ? " (" + v.reason + ")" : "";
      return '<button type="button" class="' + itemCls(s.key) + '" data-act="ref" data-ref="' + esc(s.key) + '" data-at="' + at + '">' +
        '<span class="world-item-main">#' + v.id + " " + esc(v.type) + "</span>" +
        '<span class="pill pill-' + esc(v.status) + '">' + esc(v.status) + esc(extra) + "</span>" + convTag + "</button>";
    }).join("");
  }
  const queuedItems = [];
  for (const [cid, doc] of inboxDocs) {
    for (const qItem of doc.items ?? []) {
      queuedItems.push({ cid, ...qItem });
    }
  }
  if (queuedItems.length) {
    subsHTML += '<div class="world-inbox-strip"><span>pi.inbox 排队中（' + queuedItems.length + "）</span>" +
      queuedItems.map((qItem) =>
        '<button type="button" class="' + itemCls("doc:pi.inbox@c:" + qItem.cid) + '" data-act="ref" data-ref="doc:pi.inbox@c:' + qItem.cid + '" data-at="' + at + '">' +
        '<span class="world-item-main">#' + qItem.id + '</span><span class="pill pill-queued">' + esc(qItem.mode) + "</span>" +
        (qItem.content ? '<span class="world-item-text">' + esc(qItem.content) + "</span>" : "") + "</button>"
      ).join("") + "</div>";
  }

  // Column 3: Task Ownership Tree
  const childrenOf = new Map();
  const roots = [];
  const taskById = new Map(tasks.map((t) => [t.a.id, t]));
  for (const t of tasks) {
    const parentId = t.a.owner ?? conversations.get(t.a.conversation_id)?.owner?.task_id ?? null;
    if (parentId != null && taskById.has(parentId)) {
      if (!childrenOf.has(parentId)) childrenOf.set(parentId, []);
      childrenOf.get(parentId).push(t);
    } else {
      roots.push(t);
    }
  }
  const renderTree = (list, depth) => list.map((t) => {
    const v = t.a;
    const st = v.state.status;
    const detail = v.state.checkpoint?.phase || v.state.outcome?.status || "";
    const pillCls = st === "terminal"
      ? (v.state.outcome?.status === "completed" ? "pill-completed" : "pill-bad")
      : "pill-" + st;
    const isRunOwner = liveDocs.get(v.conversation_id)?.run?.task_id === v.id;
    const convTag = multiConv ? '<span class="pill pill-pending">c:' + v.conversation_id + "</span>" : "";
    const runTag = isRunOwner ? '<span class="pill pill-run">run</span>' : "";
    const restartTag = v.restarts ? '<span class="pill pill-bad">r=' + v.restarts + "</span>" : "";
    const abortTag = v.abort_requested ? '<span class="pill pill-bad">abort</span>' : "";
    const prefix = depth > 0 ? "└ " : "";
    const node = '<div class="world-tree-node" style="--depth:' + depth + '">' +
      '<button type="button" class="' + itemCls(t.key) + '" data-act="ref" data-ref="' + esc(t.key) + '" data-at="' + at + '">' +
      '<span class="world-item-main">' + prefix + "#" + v.id + " " + esc(v.kind.replace(/^pi\./, "")) + "</span>" +
      '<span class="pill ' + pillCls + '">' + esc(st + (detail ? "/" + detail : "")) + "</span>" +
      convTag + runTag + restartTag + abortTag + "</button></div>";
    return node + renderTree(childrenOf.get(v.id) || [], depth + 1);
  }).join("");
  const treeHTML = tasks.length ? renderTree(roots, 0) : '<p class="world-empty">还没有创建 Task。</p>';

  return '<details class="world-state"' + (S.worldOpen ? " open" : "") + ' id="world-state-box">' +
    "<summary><span>第 " + at + " 次提交后的全局状态</span><small>点击任意项跳到右侧持久化详情 · 蓝条表示本步写入</small></summary>" +
    '<div class="world-grid">' +
    '<div class="world-col"><h4>对话消息 · Entries（' + entries.length + '）</h4><div class="world-list">' + entriesHTML + "</div></div>" +
    '<div class="world-col"><h4>请求与队列 · Submissions（' + submissions.length + '）</h4><div class="world-list">' + subsHTML + "</div></div>" +
    '<div class="world-col"><h4>任务所有权树 · Tasks（' + tasks.length + '）</h4><div class="world-list">' + treeHTML + "</div></div>" +
    "</div></details>";
}

/* JSON-path-aware runtime diff renderer */
function flattenDiff(prev, curr, path = "", out = new Map()) {
  if (JSON.stringify(prev) === JSON.stringify(curr)) return out;
  const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);
  if (prev === ABSENT) {
    out.set(path, "added");
    return out;
  }
  if (isObj(prev) && isObj(curr)) {
    for (const k of Object.keys(curr)) {
      const next = path ? path + "." + k : k;
      if (!Object.hasOwn(prev, k)) {
        out.set(next, "added");
      } else {
        flattenDiff(prev[k], curr[k], next, out);
      }
    }
    return out;
  }
  out.set(path, "changed");
  return out;
}

function renderAnnotatedJson(obj, diffMap, onlyChanged) {
  const lines = [];
  const walk = (val, path, indent, keyPrefix, comma) => {
    const status = diffMap.get(path) || "";
    const pad = " ".repeat(indent);
    const isObj = val && typeof val === "object" && !Array.isArray(val);
    const isArr = Array.isArray(val);

    if (status === "added" || (!isObj && !isArr)) {
      const formatted = JSON.stringify(val, null, 2);
      const split = formatted.split("\n");
      split.forEach((part, idx) => {
        const text = (idx === 0 ? pad + keyPrefix : pad) + part + (idx === split.length - 1 ? comma : "");
        lines.push({ text, cls: status });
      });
      return;
    }

    if (isArr) {
      if (!val.length) {
        lines.push({ text: pad + keyPrefix + "[]" + comma, cls: status });
        return;
      }
      const formatted = JSON.stringify(val, null, 2);
      const split = formatted.split("\n");
      split.forEach((part, idx) => {
        const text = (idx === 0 ? pad + keyPrefix : pad) + part + (idx === split.length - 1 ? comma : "");
        lines.push({ text, cls: status });
      });
      return;
    }

    const keys = Object.keys(val);
    if (!keys.length) {
      lines.push({ text: pad + keyPrefix + "{}" + comma, cls: status });
      return;
    }
    lines.push({ text: pad + keyPrefix + "{", cls: "" });
    keys.forEach((k, idx) => {
      const childPath = path ? path + "." + k : k;
      const tail = idx < keys.length - 1 ? "," : "";
      walk(val[k], childPath, indent + 2, JSON.stringify(k) + ": ", tail);
    });
    lines.push({ text: pad + "}" + comma, cls: "" });
  };
  walk(obj, "", 0, "", "");

  if (!onlyChanged) {
    return lines.map((line) =>
      '<span class="rt-line' + (line.cls ? " rt-" + line.cls : "") + '">' + esc(line.text) + "</span>"
    ).join("");
  }

  const changedIdx = new Set();
  lines.forEach((line, idx) => {
    if (line.cls) {
      for (let d = -1; d <= 1; d++) {
        if (idx + d >= 0 && idx + d < lines.length) changedIdx.add(idx + d);
      }
    }
  });
  if (!changedIdx.size) {
    return '<span class="rt-omitted">与前一次提交发布时相比，内存快照没有变化。</span>';
  }
  const out = [];
  let skipping = false;
  lines.forEach((line, idx) => {
    if (changedIdx.has(idx)) {
      skipping = false;
      out.push('<span class="rt-line' + (line.cls ? " rt-" + line.cls : "") + '">' + esc(line.text) + "</span>");
    } else if (!skipping) {
      skipping = true;
      out.push('<span class="rt-omitted">  … 未变化字段已折叠 …</span>');
    }
  });
  return out.join("");
}

function runtimeHTML(row, stored) {
  const snapshot = cur().runtime[row.q - 1];
  const isPostCrash = Boolean(cur().crashAfter && row.q === cur().crashAfter + 1);
  const canDiff = row.q > 1 && !isPostCrash;
  const prevSnapshot = canDiff ? cur().runtime[row.q - 2] : null;
  const diffMap = S.rtView !== "raw" && canDiff ? flattenDiff(prevSnapshot, snapshot) : new Map();
  const changedCount = diffMap.size;

  const liveEntries = Object.entries(snapshot.scheduler._live);
  const invEntries = Object.entries(snapshot.scheduler._invocations);
  const docCount = Object.keys(snapshot.session._docs).length;

  const summary = '<div class="rt-summary">' +
    '<span class="pill pill-running">_live: ' + liveEntries.length + "</span>" +
    (invEntries.length
      ? invEntries.map(([id, inv]) =>
          '<span class="pill ' + (inv.mode === "abort" ? "pill-bad" : "pill-placed") + '">inv #' + esc(id) + " · " + esc(inv.mode) + "</span>"
        ).join("")
      : '<span class="pill pill-pending">_invocations: 0</span>') +
    '<span class="pill pill-run">_docs: ' + docCount + "</span></div>";

  const onlyLabel = canDiff ? "只看变化" + (changedCount ? " (" + changedCount + ")" : "") : "只看变化";
  const controls = '<div class="rt-controls" role="group" aria-label="运行时 JSON 显示方式">' +
    [["diff", "高亮变化"], ["only", onlyLabel], ["raw", "纯 JSON"]].map(([mode, label]) =>
      '<button type="button" data-act="rt-view" data-rt="' + mode + '" aria-pressed="' + (S.rtView === mode) + '">' + label + "</button>"
    ).join("") + "</div>";

  const resetBanner = isPostCrash
    ? '<p class="rt-reset-note">新进程刚刚重建内存：_invocations 和 _docs 全为空，_live 直接从存储恢复。</p>'
    : "";

  const codeBody = S.rtView === "raw" || (!canDiff && S.rtView === "diff")
    ? esc(JSON.stringify(snapshot, null, 2))
    : renderAnnotatedJson(snapshot, canDiff ? diffMap : flattenDiff(ABSENT, snapshot), S.rtView === "only");

  const taskIds = new Set([
    ...Object.keys(snapshot.scheduler._live),
    ...Object.keys(snapshot.scheduler._invocations),
  ]);
  const keys = [
    ...[...taskIds].map((id) => "task:" + id),
    ...Object.keys(snapshot.session._docs).map((address) => "doc:" + address),
  ];
  const links = keys
    .filter((key) => stored.has(key))
    .map((key) => refButton(key, recordTitle(stored.get(key).item), "", row.q))
    .join("");

  return '<section class="observe-pane runtime-pane" aria-label="运行时状态">' +
    '<div class="pane-title"><h3>运行时状态</h3><span>第 ' + row.q + " 次提交发布时</span></div>" +
    '<div class="runtime-header-bar">' + summary + controls + "</div>" +
    resetBanner +
    '<p class="pane-note">字段名沿用 Python 代码。绿条为新增字段，黄条为本步变化（相对前一提交）。Task 省略时间戳。</p>' +
    '<pre class="runtime-json" tabindex="0" aria-label="运行时快照 JSON"><code>' + codeBody + "</code></pre>" +
    (links ? '<div class="relations"><h4>相关存储记录</h4><div class="ref-list">' + links + "</div></div>" : "") +
    "</section>";
}

/* Storage inspector */
function previewValue(value) {
  if (value === ABSENT) return "无此字段";
  const json = JSON.stringify(value);
  return json.length > 85 ? json.slice(0, 84) + "…" : json;
}

function fieldValues(before, after, compare = before !== ABSENT) {
  const value = (v) => '<code class="field-value">' + esc(previewValue(v)) + "</code>";
  return !compare
    ? value(after)
    : value(before) + '<span class="field-arrow" aria-label="变为">→</span>' + value(after);
}

function fieldChanges(before, after, prefix = "") {
  if (JSON.stringify(before) === JSON.stringify(after)) return [];
  const object = (v) => v && typeof v === "object" && !Array.isArray(v);
  if (object(before) && object(after)) {
    const keys = new Set([...Object.keys(after), ...Object.keys(before)]);
    return [...keys].flatMap((key) => {
      const path = /^[a-zA-Z_$][\w$]*$/.test(key) ? (prefix ? prefix + "." : "") + key
        : prefix + "[" + JSON.stringify(key) + "]";
      return fieldChanges(
        Object.hasOwn(before, key) ? before[key] : ABSENT,
        Object.hasOwn(after, key) ? after[key] : ABSENT,
        path
      );
    });
  }
  return [{ path: prefix, before, after }];
}

function recordFields(item, previous) {
  const updates = previous ? fieldChanges(previous.a, item.a)
    : Object.entries(item.a).map(([path, after]) => ({ path, before: ABSENT, after }));
  const label = previous ? "记录字段发生了什么变化" : "新记录里写了哪些字段";
  const diff = updates.map(({ path, before, after }) => "<dt><code>" + esc(path) +
    "</code></dt><dd>" + fieldValues(before, after, Boolean(previous)) + "</dd>").join("");
  return '<section class="storage-fields"><h4>' + label + "</h4>" +
    (diff ? '<dl class="field-list">' + diff + "</dl>" : '<p class="muted">展示的字段没有变化。</p>') + "</section>";
}

function sqliteColumns(item) {
  const a = item.a;
  switch (item.c) {
    case 0: return [["id", a.id]];
    case 1: return [["id", a.id], ["conversation_id", a.conversation_id], ["request_id", a.request_id ?? null]];
    case 2: return [["id", a.id], ["conversation_id", a.conversation_id]];
    case 3: return [["id", a.id], ["status", a.state.status]];
    case 4: {
      const [kind, key] = item.key.slice("doc:".length).split("@");
      return [["kind", kind], ["key", key]];
    }
  }
  return [];
}

function sqliteDetail(item, previous, beforeCommit) {
  const cleanup = item.n === 2;
  let columns = "", jsonColumn = "", note;
  if (cleanup) {
    const prefix = "@" + item.a.retire;
    const matches = [...beforeCommit.keys()].filter((key) => key.startsWith("doc:") && key.endsWith(prefix));
    note = matches.length
      ? "按 <code>key</code> 删除这个范围下的 " + matches.length + " 条 Document。"
      : "按 <code>key</code> 查找任务文档。这一步没有匹配的行。";
    columns = "<dt><code>WHERE key</code></dt><dd>" + fieldValues(ABSENT, item.a.retire) + "</dd>";
  } else {
    const beforeCols = new Map(previous ? sqliteColumns(previous) : []);
    columns = sqliteColumns(item).map(([column, after]) => {
      const before = beforeCols.has(column) ? beforeCols.get(column) : ABSENT;
      return "<dt><code>" + esc(column) + "</code></dt><dd>" +
        fieldValues(Object.is(before, after) ? ABSENT : before, after) + "</dd>";
    }).join("");
    jsonColumn = '<details class="sqlite-json" open><summary><code>json</code> · 记录内容（录制节选）</summary>' +
      "<pre><code>" + pj(item.a) + "</code></pre></details>";
    note = item.c === 3
      ? "整条 Task 存进 <code>json</code>，<code>state.status</code> 也单独写进 <code>status</code> 列，便于按状态查询。"
      : "其余字段随整条记录保存在 <code>json</code> 列中。";
  }
  return '<section class="sqlite-section"><h4>' + (cleanup ? "SQLite 删除条件" : "SQLite 存储列") + "</h4>" +
    '<div class="sqlite-columns"><dl class="field-list">' + columns + "</dl>" + jsonColumn + "</div>" +
    '<p class="tip">' + note + "</p></section>";
}

function recordHTML(row, state) {
  const selectedAt = S.open.refAt ?? row.q;
  const versions = COMMIT_INDEXES[S.sc];
  const recordState = versions[selectedAt];
  const selected = S.open.ref ? recordState.get(S.open.ref) : null;
  const index = S.open.i;
  const item = selected ? selected.item : row.x[index];
  const pickAnswer = S.mode === "quiz" && S.q?.answered && !S.q.finished && curQ().kind === "pick"
    ? curQ().answer : null;
  const groups = new Map();
  for (const [i, write] of row.x.entries()) {
    const table = STORAGE_TABLES[write.c];
    const on = !selected && index === i;
    const operation = write.n === 2 ? "" : write.n ? "新增 " : "更新 ";
    const button = '<button type="button" class="atom c' + write.c + " " + chipCls(write) +
      (on ? " on" : "") + (pickAnswer && pickAnswer === write.key ? " pick-answer" : "") +
      '" aria-pressed="' + on + '" data-act="write" data-q="' + row.q + '" data-i="' + i + '">' +
      operation + esc(write.t) + "</button>";
    if (!groups.has(table)) groups.set(table, []);
    groups.get(table).push(button);
  }
  const writes = [...groups].map(([table, buttons]) =>
    '<div class="storage-group"><code>' + esc(table) + '</code><div class="atoms">' + buttons.join("") + "</div></div>"
  ).join("");

  const docLinks = [...state.values()].filter((v) => v.item.c === 4).map(({ item: doc }) => {
    const address = doc.key.split("@").at(-1);
    const role = DOC_ROLES[doc.t]?.[0];
    return refButton(doc.key, doc.t + " · " + address + (role ? " · " + role : ""));
  }).join("");

  let record = '<p class="muted">选中一条写入，查看字段变化和存储列。</p>';
  if (item) {
    const writtenAt = selected?.row ?? row.q;
    const beforeCommit = versions[writtenAt - 1];
    const previous = item.key && beforeCommit.get(item.key)?.item;
    const title = item.n === 2 ? item.a.retire : recordTitle(item);
    const action = item.n === 2 ? "清理" : previous ? "更新" : "新增";
    const explanation = item.n === 2 ? "" : DOC_ROLES[item.t]?.[1] || TIP[item.c];
    const earlier = selected && writtenAt !== row.q
      ? "<span>此版本写于第 " + writtenAt + " 次提交</span>" : "";
    const links = recordLinks(item, recordState);
    const related = links.length ? '<div class="relations"><h4>关联字段</h4><div class="ref-list">' +
      links.map(({ field, key }) => refButton(key, recordTitle(recordState.get(key).item), field, selectedAt)).join("") +
      "</div></div>" : "";
    record = '<div class="record-view storage-explanation" tabindex="-1"><div class="record-title"><h4><code>' +
      esc(STORAGE_TABLES[item.c]) + "</code> · " + esc(action + " " + title) + "</h4>" + earlier + "</div>" +
      (explanation ? '<p class="tip">' + esc(explanation) + "</p>" : "") +
      (item.n === 2 ? "" : recordFields(item, previous)) +
      sqliteDetail(item, previous, beforeCommit) + related + "</div>";
  }
  return '<section class="observe-pane storage-pane" aria-label="持久化记录">' +
    '<div class="pane-title"><h3>持久化记录</h3><span>本次提交 · ' + row.x.length + " 项</span></div>" +
    '<p class="pane-note">运行录自 <code>MemoryStorage</code>。下方按 SQLite 的表结构标出同一批写入。</p>' +
    '<div class="storage-groups">' + writes + "</div>" + record +
    '<p class="pane-note">同一事务也会把 <code>meta</code> 表里 <code>key=\'seq\'</code> 的 <code>value</code> 加 1。</p>' +
    (docLinks ? '<div class="document-links"><h4>提交后已有的文档</h4><div class="ref-list">' + docLinks + "</div></div>" : "") +
    "</section>";
}

/* Guided learning stops & comprehension check */
function activeStop() {
  return LEARNING[cur().id].stops.find((stop) => stop.q === S.open?.q);
}

function navigateStop(stop) {
  const row = cur().rows[stop.q - 1];
  const i = row.x.findIndex((item) => item.key === stop.key);
  S.open = i >= 0 ? { q: stop.q, i } : { q: stop.q, i: -1, ref: stop.key };
}

function guideHTML() {
  if (S.mode !== "learn") return "";
  const guide = LEARNING[cur().id];
  return '<section class="reading-guide" aria-label="关键步骤导读"><div class="reading-heading">' +
    "<p>" + esc(guide.goal) + '</p><button type="button" class="btn" data-act="show-all" aria-pressed="' + S.revealAll + '">' +
    (S.revealAll ? "按步骤展开" : "展开完整时序") + "</button></div>" +
    '<nav class="reading-stops" aria-label="跳到关键步骤">' + guide.stops.map((stop, index) =>
      '<button type="button" data-act="guide" data-stop="' + index + '" aria-pressed="' + (S.open?.q === stop.q) + '">' +
      "<span>提交 " + stop.q + "</span><b>" + esc(stop.title) + "</b></button>"
    ).join("") + "</nav></section>";
}

function focusHTML(row) {
  if (S.mode !== "learn") return "";
  const stop = activeStop();
  if (!stop) return "";
  const at = S.open.runtimeAt ?? row.q;
  const state = COMMIT_INDEXES[S.sc][at];
  const links = stop.links.filter((link) => state.has(link.from) && state.has(link.to)).map((link) =>
    "<li>" + refButton(link.from, recordTitle(state.get(link.from).item), "", at) +
    "<code>" + esc(link.field) + '</code><span aria-hidden="true">→</span>' +
    refButton(link.to, recordTitle(state.get(link.to).item), "", at) + "</li>"
  ).join("");
  return '<section class="step-focus" aria-label="本步重点"><h3>' + esc(stop.title) + "</h3>" +
    "<p>" + esc(stop.why) + "</p>" +
    (at === row.q ? '<p class="runtime-reason"><strong>内存里</strong> ' + esc(stop.runtime) + "</p>" : "") +
    (links ? '<ul class="relation-paths" aria-label="记录关联">' + links + "</ul>" : "") + "</section>";
}

function checkHTML() {
  const check = LEARNING[cur().id].check;
  const result = S.lessonAnswer;
  const options = check.options.map((option, i) => {
    let cls = "check-option";
    if (result === i) cls += i === check.answer ? " is-right" : " is-wrong";
    return '<button type="button" class="' + cls + '" data-act="lesson-answer" data-answer="' + i +
      '" aria-pressed="' + (result === i) + '">' + esc(option) + "</button>";
  }).join("");
  const feedback = result === null ? "" :
    '<div class="lesson-feedback ' + (result === check.answer ? "correct" : "incorrect") + '" role="status">' +
    "<strong>" + (result === check.answer ? "答对了。" : "不对：") + "</strong> " +
    esc(check.optionFeedback[result]) +
    '<button type="button" class="btn" data-act="check-evidence">查看依据 · 第 ' + check.evidenceStep + " 次提交</button></div>";
  return '<h2>用一个问题确认理解</h2><p class="lesson-check-prompt">' + esc(check.prompt) + "</p>" +
    '<div class="check-options">' + options + "</div>" + feedback;
}

function detailHTML(r) {
  const state = COMMIT_INDEXES[S.sc][r.q];
  const last = S.mode === "learn" ? cur().rows.length : visibleRows().length;
  const event = activeMessage(r);
  const at = S.open.runtimeAt ?? r.q;
  const sample = cur().rows[at - 1];
  const src = commitSource(r);
  const srcLink = src
    ? '<a class="commit-source-link" href="' + esc(SOURCE_BASE + src.path + "#L" + src.line) +
      '" target="_blank" rel="noopener">源码：' + esc(src.path.replace(/^pi_durable\//, "") + ":" + src.line + " · " + src.fn) + " ↗</a>"
    : "";
  const title = event
    ? PARTICIPANT_BY_ID.get(event.from).title + " → " + PARTICIPANT_BY_ID.get(event.to).title + " · " + event.label
    : "写入 DB · " + r.x.length + " 项";
  const context = event ? (event.after ? "本次写入之后。" : "本次写入之前。") + event.detail : r.note;
  const toggles = r.q <= 1 ? "" : '<div class="snapshot-controls" aria-label="选择运行时采样时刻">' +
    '<button type="button" class="btn" data-act="sample" data-at="' + (r.q - 1) + '" aria-pressed="' + (at < r.q) + '">前一提交后</button>' +
    '<button type="button" class="btn" data-act="sample" data-at="' + r.q + '" aria-pressed="' + (at === r.q) + '">本次提交后</button></div>';
  return '<section class="det inspector" id="commit-inspector" aria-label="第 ' + r.q + ' 次提交详情">' +
    '<div class="inspector-header"><div class="inspector-title-row"><h2>第 ' + r.q + " 次提交 <span>/ " + last + "</span></h2>" + srcLink + "</div>" +
    '<div class="observer-nav">' +
    '<button type="button" class="btn" data-act="step" data-dir="-1"' + (r.q === 1 ? " disabled" : "") + ">上一步</button>" +
    '<button type="button" class="btn" data-act="step" data-dir="1"' + (r.q >= last ? " disabled" : "") + ">下一步</button>" +
    '<button type="button" class="btn" data-act="back-to-diagram">回到图</button>' +
    '<span class="kbd-hint">支持 ← / →</span></div></div>' +
    '<p class="selection-context"><b>' + esc(title) + "</b><span>" + esc(context) + "</span></p>" +
    toggles + focusHTML(r) + worldStateHTML(r, state) +
    '<div class="observe-grid">' + runtimeHTML(sample, COMMIT_INDEXES[S.sc][at]) + recordHTML(r, state) + "</div></section>";
}

function quizHTML() {
  const sc = cur(), Q = S.q, total = sc.quiz.length;
  if (Q.finished) {
    const nextEl = document.querySelector("[data-next-article]");
    return '<div class="quiz"><div class="qhead"><span>' + esc(sc.title) + " · 练习完成</span></div>" +
      '<p class="qprompt">答对 ' + Q.score + " / " + total + " 题（按第一次作答计）。</p>" +
      '<div class="row"><button type="button" class="btn primary" data-act="restart">再做一遍</button>' +
      (nextEl ? '<a class="btn" href="' + esc(nextEl.getAttribute("href")) + '">下一篇</a>' : "") +
      '<button type="button" class="btn" data-act="mode" data-mode="learn">回到时序图</button></div></div>';
  }
  const q = curQ();
  let body = "";
  if (q.kind === "choice") {
    const type = q.multi ? "checkbox" : "radio", ans = [].concat(q.answer);
    body += '<div class="opts">' + q.options.map((o, i) => {
      let c = "opt";
      if (Q.answered) { if (ans.includes(i)) c += " right"; else if (Q.chosen.includes(i)) c += " wrong"; }
      const id = "q-" + S.sc + "-" + Q.i + "-" + i;
      return '<label class="' + c + '" for="' + id + '"><input type="' + type + '" name="q" value="' + i + '" id="' + id + '"' +
        (Q.chosen.includes(i) ? " checked" : "") + (Q.answered ? " disabled" : "") + "><span>" + esc(o) + "</span></label>";
    }).join("") + "</div>";
    if (!Q.answered) body += '<p class="err" id="qerr"' + (Q.err ? "" : " hidden") + '>先选一个答案再提交。</p><div class="row"><button type="button" class="btn primary" data-act="submit">提交答案</button></div>';
  } else if (!Q.answered) {
    body += '<p class="hint">点图中的 DB 写入箭头，再在下方「持久化记录」中点一条记录作答。</p><div class="row"><button type="button" class="btn" data-act="giveup">显示答案</button></div>';
  }
  if (Q.answered) {
    let fb = "<b>" + (Q.ok ? "答对了。" : q.kind === "pick"
      ? (Q.picked ? "不对，你点的是 " + esc(nameOf(Q.picked)) + "。正确答案是 " + esc(nameOf(q.answer)) + "。" : "正确答案是 " + esc(nameOf(q.answer)) + "。")
      : "不对，正确答案已标成绿色。") + "</b> " + esc(q.explain);
    if (Q.revealed) fb += "<br><br><b>第 " + (q.step + 1) + " 次提交实际发生的：</b>" + esc(sc.rows[q.step].note);
    body += '<div class="fb ' + (Q.ok ? "ok" : "no") + '">' + fb + '</div><div class="row">' +
      (q.reveal && !Q.revealed ? '<button type="button" class="btn" data-act="reveal">看看下一次提交写了什么</button>' : "") +
      '<button type="button" class="btn primary" data-act="nextq">' + (Q.i === total - 1 ? "查看成绩" : "下一题") + "</button></div>";
  }
  const shown = Q.revealed ? q.step + 1 : q.step;
  return '<div class="quiz"><div class="qhead"><span>' + esc(sc.title) + " · 练习 " + (Q.i + 1) + " / " + total +
    "</span><span>时序图显示到第 " + shown + " 次提交</span><span>已答对 " + Q.score + "</span></div>" +
    '<p class="qprompt">' + esc(q.prompt) + "</p>" + body + "</div>";
}

function render() {
  const active = document.activeElement;
  const control = active?.matches("[data-act]") ? { ...active.dataset } : null;
  $("#mode-learn").setAttribute("aria-pressed", String(S.mode === "learn"));
  $("#mode-quiz").setAttribute("aria-pressed", String(S.mode === "quiz"));
  $("#quiz").innerHTML = S.mode === "quiz" ? quizHTML() : "";
  const rows = visibleRows();
  const scroll = $("#sequence-scroll");
  const { scrollTop, scrollLeft } = scroll;
  $("#seq").innerHTML = sequenceHTML(rows);
  $("#step-detail").innerHTML = S.open ? detailHTML(cur().rows[S.open.q - 1]) : "";
  $("#reading-guide").innerHTML = guideHTML();
  $("#lesson-check").innerHTML = checkHTML();
  scroll.scrollTop = scrollTop;
  scroll.scrollLeft = scrollLeft;
  const worldBox = $("#world-state-box");
  if (worldBox) {
    worldBox.addEventListener("toggle", () => { S.worldOpen = worldBox.open; });
  }
  if (active && !active.isConnected && control) {
    const same = [...document.querySelectorAll("[data-act]")].find((el) =>
      !el.disabled && Object.entries(control).every(([key, value]) => el.dataset[key] === value));
    same?.focus({ preventScroll: true });
  }
}

function startQuiz() { S.q = { i: 0, score: 0, finished: false }; loadQ(); }
function loadQ() { Object.assign(S.q, { answered: false, chosen: [], ok: false, revealed: false, picked: null, err: false }); S.open = null; render(); }
function openDefault() { navigateStop(LEARNING[cur().id].stops[0]); }

function stepBy(dir) {
  if (!S.open) return;
  const q = S.open.q + dir;
  const last = S.mode === "learn" ? cur().rows.length : visibleRows().length;
  if (q < 1 || q > last) return;
  S.open = { q, i: 0 };
  render();
  showStep(true);
}

document.addEventListener("click", (e) => {
  const a = e.target.closest("[data-act]");
  if (!a) return;
  const act = a.dataset.act;
  if (act === "write") {
    const q = Number(a.dataset.q), i = Number(a.dataset.i), x = cur().rows[q - 1].x[i];
    if (S.mode === "quiz" && S.q && !S.q.finished && !S.q.answered && curQ().kind === "pick" && x.key) {
      Object.assign(S.q, { answered: true, picked: x.key, ok: x.key === curQ().answer });
      if (S.q.ok) S.q.score++;
    }
    S.open = { ...S.open, q, i, ref: null, refAt: null };
    render();
    if (S.mode === "quiz" && S.q?.answered && !S.q.finished && curQ().kind === "pick") $("#quiz .fb")?.scrollIntoView({ block: "nearest" });
  } else if (act === "event" || act === "db") {
    const q = Number(a.dataset.q);
    const event = act === "event" ? Number(a.dataset.e) : null;
    const triggered = event !== null ? EVENT_ROWS[S.sc][q - 1][event] : null;
    S.open = { q, i: 0, event, runtimeAt: triggered && !triggered.after && q > 1 ? q - 1 : q };
    render();
    showStep();
  } else if (act === "article-step") {
    e.preventDefault();
    S.mode = "learn";
    S.open = { q: Number(a.dataset.q), i: 0 };
    render();
    $("#timeline").scrollIntoView({ block: "start" });
    showStep(true);
    $('.sequence-group[data-step="' + S.open.q + '"] button[data-act="db"]')?.focus({ preventScroll: true });
  } else if (act === "guide") {
    navigateStop(LEARNING[cur().id].stops[Number(a.dataset.stop)]);
    render();
    showStep(true);
  } else if (act === "show-all") {
    S.revealAll = !S.revealAll;
    render();
    showStep(true);
  } else if (act === "map-tab") {
    const chosen = a.dataset.map;
    document.querySelectorAll('[data-act="map-tab"]').forEach((btn) => {
      btn.setAttribute("aria-pressed", String(btn.dataset.map === chosen));
    });
    document.querySelectorAll("[data-map-panel]").forEach((panel) => {
      panel.hidden = panel.dataset.mapPanel !== chosen;
    });
  } else if (act === "rt-view") {
    S.rtView = a.dataset.rt;
    render();
  } else if (act === "lesson-answer") {
    S.lessonAnswer = Number(a.dataset.answer);
    if (S.lessonAnswer === LEARNING[cur().id].check.answer) markScenarioDone(cur().id);
    $("#lesson-check").innerHTML = checkHTML();
    $('#lesson-check [data-answer="' + S.lessonAnswer + '"]')?.focus({ preventScroll: true });
  } else if (act === "check-evidence") {
    const check = LEARNING[cur().id].check;
    S.mode = "learn";
    navigateStop({ q: check.evidenceStep, key: check.evidenceKey });
    render();
    $("#timeline").scrollIntoView({ block: "start" });
    showStep(true);
  } else if (act === "step") {
    stepBy(Number(a.dataset.dir));
    if (document.activeElement === document.body) {
      $('#commit-inspector [data-act="step"]:not(:disabled)')?.focus({ preventScroll: true });
    }
  } else if (act === "sample") {
    S.open.runtimeAt = Number(a.dataset.at);
    render();
  } else if (act === "ref") {
    const at = a.dataset.at ? Number(a.dataset.at) : S.open.q;
    const state = COMMIT_INDEXES[S.sc][at];
    if (!state.has(a.dataset.ref)) return;
    Object.assign(S.open, { i: -1, ref: a.dataset.ref, refAt: at });
    render();
    $("#commit-inspector .record-view")?.focus({ preventScroll: true });
  } else if (act === "back-to-diagram") {
    const chosen = $('.sequence-group[data-step="' + S.open.q + '"] button[aria-pressed="true"]');
    if (chosen) chosen.focus({ preventScroll: true });
    $("#sequence-scroll").scrollIntoView({ block: "start", inline: "nearest" });
    showStep(true);
  } else if (act === "mode") {
    S.mode = a.dataset.mode;
    if (S.mode === "quiz") startQuiz();
    else { openDefault(); render(); }
  } else if (act === "submit") {
    const chosen = Array.from(document.querySelectorAll('input[name="q"]:checked')).map((x) => +x.value);
    if (!chosen.length) { S.q.err = true; const el = $("#qerr"); if (el) el.hidden = false; return; }
    const want = [].concat(curQ().answer).slice().sort().join(",");
    Object.assign(S.q, { chosen, answered: true, err: false, ok: chosen.slice().sort().join(",") === want });
    if (S.q.ok) S.q.score++;
    render();
  } else if (act === "giveup") {
    Object.assign(S.q, { answered: true, ok: false, picked: null });
    render();
  } else if (act === "reveal") {
    S.q.revealed = true;
    S.open = { q: curQ().step + 1, i: -1 };
    render();
  } else if (act === "nextq") {
    if (S.q.i >= cur().quiz.length - 1) {
      S.q.finished = true;
      markScenarioDone(cur().id);
      render();
    } else {
      S.q.i++;
      loadQ();
    }
  } else if (act === "restart") {
    startQuiz();
  }
});

document.addEventListener("change", (e) => {
  if (e.target.name !== "q" || !S.q) return;
  S.q.chosen = Array.from(document.querySelectorAll('input[name="q"]:checked')).map((input) => Number(input.value));
  S.q.err = false;
  const message = $("#qerr");
  if (message) message.hidden = true;
});

document.addEventListener("keydown", (e) => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.target instanceof Element && e.target.closest("input, textarea, select")) return;
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    stepBy(-1);
  } else if (e.key === "ArrowRight") {
    e.preventDefault();
    stepBy(1);
  }
});

syncNavProgress();
openDefault();
render();
showStep(true);
